// Reusable Player Avatar Component with Custom Image & Fallback support
function PlayerAvatar({ name, customUri = null, size = 34, borderColor = '#10b981', style = {} }) {
  const [imgError, setImgError] = useState(false);
  const cleanName = (name || '').replace(/\s*\([^)]*\)/g, '').trim();
  const avatarUrl = customUri || PLAYER_AVATARS[cleanName] || PLAYER_AVATARS[name];

  useEffect(() => {
    setImgError(false);
  }, [avatarUrl, customUri]);

  const getInitials = n => {
    if (!n) return '🏏';
    const parts = n.split(' ');
    if (parts.length >= 2) return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
    return parts[0].slice(0, 2).toUpperCase();
  };

  if (!avatarUrl || imgError) {
    return (
      <View
        style={[
          {
            width: size,
            height: size,
            borderRadius: size / 2,
            backgroundColor: '#1e293b',
            borderWidth: 1.5,
            borderColor: borderColor || '#334155',
            justifyContent: 'center',
            alignItems: 'center',
          },
          style,
        ]}
      >
        <Text style={{ color: '#ffffff', fontSize: Math.max(9, Math.round(size * 0.38)), fontWeight: '900' }}>
          {getInitials(cleanName)}
        </Text>
      </View>
    );
  }

  return (
    <View
      style={[
        {
          width: size,
          height: size,
          borderRadius: size / 2,
          backgroundColor: '#0f172a',
          borderWidth: 1.5,
          borderColor: borderColor || '#10b981',
          overflow: 'hidden',
          justifyContent: 'center',
          alignItems: 'center',
        },
        style,
      ]}
    >
      <Image
        key={avatarUrl || "avatar"}
        source={{ uri: avatarUrl }}
        style={{ width: size, height: size }}
        resizeMode="cover"
        onError={() => setImgError(true)}
      />
    </View>
  );
}

// Universal Cross-Platform Live QR Camera Component (Web + Native Android / iOS)
function UniversalLiveQrCameraView({ onScan, isLocked, active, cameraPermission, requestCameraPermission }) {
  const _document = typeof document !== 'undefined' ? document : null;
  const _navigator = typeof navigator !== 'undefined' ? navigator : null;
  const _FileReader = typeof FileReader !== 'undefined' ? FileReader : null;
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const animFrameRef = useRef(null);
  const activeStreamRef = useRef(null);
  const fileInputRef = useRef(null);
  const [webError, setWebError] = useState(null);
  const [cameraLoading, setCameraLoading] = useState(true);
  const [facingMode, setFacingMode] = useState('environment'); // 'environment' (back) or 'user' (front)

  // Auto-request permission on native devices when active
  useEffect(() => {
    if (Platform.OS !== 'web' && active && !cameraPermission?.granted && requestCameraPermission) {
      requestCameraPermission().catch(() => {});
    }
  }, [active, cameraPermission?.granted]);

  // Web HTML5 MediaStream Camera Handler with real-time frame scanning via jsQR
  useEffect(() => {
    if (Platform.OS === 'web' && active) {
      let mounted = true;
      let failsafeTimer = null;

      const stopCurrentStream = () => {
        if (activeStreamRef.current) {
          try {
            activeStreamRef.current.getTracks().forEach(t => t.stop());
          } catch (e) {}
          activeStreamRef.current = null;
        }
      };

      const scanWebFrames = () => {
        if (!canvasRef.current && typeof document !== 'undefined') {
          if (_document) { canvasRef.current = _document.createElement('canvas'); }
        }
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { willReadFrequently: true });

        const processFrame = () => {
          if (!mounted) return;
          const video = videoRef.current;
          if (video && video.readyState >= 2 && video.videoWidth > 0 && video.videoHeight > 0) {
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
            try {
              const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
              const code = jsQR(imgData.data, imgData.width, imgData.height, {
                inversionAttempts: 'attemptBoth',
              });
              if (code && code.data && !isLocked) {
                onScan(code.data);
                return;
              }
            } catch (e) {}
          }
          animFrameRef.current = requestAnimationFrame(processFrame);
        };

        if (animFrameRef.current) cancelAnimationFrame(animFrameRef.current);
        animFrameRef.current = requestAnimationFrame(processFrame);
      };

      const initWebCamera = async () => {
        setCameraLoading(true);
        setWebError(null);
        stopCurrentStream();

        try {
          if (!_navigator?.mediaDevices || !_navigator?.mediaDevices?.getUserMedia) {
            setWebError('Camera not supported in this browser context (HTTPS or localhost required)');
            setCameraLoading(false);
            return;
          }

          let mediaStream = null;
          try {
            // Attempt with facingMode constraint
            mediaStream = await _navigator.mediaDevices.getUserMedia({
              video: {
                facingMode: facingMode === 'environment' ? { ideal: 'environment' } : 'user',
                width: { ideal: 640 },
                height: { ideal: 640 },
              },
              audio: false,
            });
          } catch (firstErr) {
            try {
              // Fallback to basic video constraint for laptops/webcams
              mediaStream = await _navigator.mediaDevices.getUserMedia({
                video: true,
                audio: false,
              });
            } catch (secondErr) {
              throw secondErr;
            }
          }

          if (!mounted) {
            mediaStream.getTracks().forEach(t => t.stop());
            return;
          }

          activeStreamRef.current = mediaStream;

          if (videoRef.current) {
            const v = videoRef.current;
            v.srcObject = mediaStream;
            v.muted = true;
            v.playsInline = true;
            v.setAttribute('playsinline', 'true');
            v.setAttribute('muted', 'true');
            v.setAttribute('autoplay', 'true');
            try {
              await v.play();
            } catch (e) {}
            setCameraLoading(false);
            scanWebFrames();
          }

          // Failsafe timer: dismiss loading spinner after 2 seconds
          failsafeTimer = setTimeout(() => {
            if (mounted) setCameraLoading(false);
          }, 2000);

        } catch (err) {
          console.warn('Web camera stream error:', err);
          if (mounted) {
            setCameraLoading(false);
            if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
              setWebError('Camera permission blocked by browser');
            } else if (err.name === 'NotFoundError' || err.name === 'DevicesNotFoundError') {
              setWebError('No camera device detected on this system');
            } else {
              setWebError('Could not start camera feed (' + (err.message || 'Check camera access') + ')');
            }
          }
        }
      };

      initWebCamera();

      return () => {
        mounted = false;
        if (failsafeTimer) clearTimeout(failsafeTimer);
        if (animFrameRef.current) {
          cancelAnimationFrame(animFrameRef.current);
          animFrameRef.current = null;
        }
        stopCurrentStream();
      };
    }
  }, [active, isLocked, facingMode]);

  // Handle Scan from local Image File / Photo
  const handleScanImageFile = (e) => {
    const file = e?.target?.files?.[0];
    if (!file) return;
    if (!_FileReader) return; const reader = new _FileReader();
    reader.onload = (event) => {
      if (typeof window !== 'undefined') {
        const img = new window.Image();
        img.onload = () => {
          if (!_document) return; const canvas = _document.createElement('canvas');
          canvas.width = img.width;
          canvas.height = img.height;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0);
          const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
          const code = jsQR(imgData.data, imgData.width, imgData.height, {
            inversionAttempts: 'attemptBoth',
          });
          if (code && code.data) {
            onScan(code.data);
          } else {
            alert('Could not detect QR code in this image. Please try another QR photo or use the quick test buttons below.');
          }
        };
        img.src = event.target.result;
      }
    };
    reader.readAsDataURL(file);
  };

  // Web Browser Platform
  if (Platform.OS === 'web') {
    if (webError) {
      return (
        <View style={{ padding: 14, alignItems: 'center', justifyContent: 'center', width: '100%', height: '100%', backgroundColor: '#0f172a' }}>
          <Text style={{ fontSize: 28, marginBottom: 4 }}>📷</Text>
          <Text style={{ color: '#f87171', fontSize: 12, fontWeight: 'bold', textAlign: 'center', marginBottom: 4 }}>
            {webError}
          </Text>
          <Text style={{ color: '#94a3b8', fontSize: 10, textAlign: 'center', marginBottom: 12 }}>
            You can allow camera access, select a QR image file, or use the 1-tap test chips below:
          </Text>
          
          <View style={{ flexDirection: 'row', gap: 8, flexWrap: 'wrap', justifyContent: 'center' }}>
            <TouchableOpacity
              style={{
                backgroundColor: '#10b981',
                paddingHorizontal: 12,
                paddingVertical: 7,
                borderRadius: 8,
              }}
              onPress={() => {
                if (_navigator?.mediaDevices?.getUserMedia) {
                  _navigator.mediaDevices.getUserMedia({ video: true }).then(s => {
                    setWebError(null);
                    s.getTracks().forEach(t => t.stop());
                  }).catch(() => {});
                }
              }}
            >
              <Text style={{ color: '#022c22', fontSize: 11, fontWeight: '900' }}>🔄 Retry Camera</Text>
            </TouchableOpacity>

            <TouchableOpacity
              style={{
                backgroundColor: '#0284c7',
                paddingHorizontal: 12,
                paddingVertical: 7,
                borderRadius: 8,
              }}
              onPress={() => {
                if (fileInputRef.current) {
                  fileInputRef.current.click();
                }
              }}
            >
              <Text style={{ color: '#ffffff', fontSize: 11, fontWeight: '900' }}>📁 Pick QR Image</Text>
            </TouchableOpacity>
          </View>

          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            style={{ display: 'none' }}
            onChange={handleScanImageFile}
          />
        </View>
      );
    }
    return (
      <View style={{ width: '100%', height: '100%', position: 'relative', overflow: 'hidden', backgroundColor: '#000000' }}>
        <video
          ref={(el) => {
            videoRef.current = el;
            if (el && activeStreamRef.current && el.srcObject !== activeStreamRef.current) {
              el.srcObject = activeStreamRef.current;
              el.muted = true;
              el.playsInline = true;
              el.play().catch(() => {});
            }
          }}
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            borderRadius: 14,
            display: 'block',
          }}
          autoPlay
          playsInline
          muted
          onLoadedMetadata={() => setCameraLoading(false)}
          onCanPlay={() => setCameraLoading(false)}
          onPlay={() => setCameraLoading(false)}
          onPlaying={() => setCameraLoading(false)}
        />

        {/* In-viewfinder Floating Controls: Switch Camera + Pick Image */}
        <View style={{ position: 'absolute', bottom: 8, right: 8, flexDirection: 'row', gap: 6, zIndex: 10 }}>
          <TouchableOpacity
            style={{
              backgroundColor: 'rgba(15, 23, 42, 0.85)',
              paddingHorizontal: 8,
              paddingVertical: 4,
              borderRadius: 6,
              borderWidth: 1,
              borderColor: '#38bdf8',
            }}
            onPress={() => {
              setFacingMode(prev => prev === 'environment' ? 'user' : 'environment');
            }}
          >
            <Text style={{ color: '#38bdf8', fontSize: 10, fontWeight: 'bold' }}>
              🔄 {facingMode === 'environment' ? 'Front Cam' : 'Back Cam'}
            </Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={{
              backgroundColor: 'rgba(15, 23, 42, 0.85)',
              paddingHorizontal: 8,
              paddingVertical: 4,
              borderRadius: 6,
              borderWidth: 1,
              borderColor: '#10b981',
            }}
            onPress={() => {
              if (fileInputRef.current) {
                fileInputRef.current.click();
              }
            }}
          >
            <Text style={{ color: '#10b981', fontSize: 10, fontWeight: 'bold' }}>📁 Photo</Text>
          </TouchableOpacity>
        </View>

        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          style={{ display: 'none' }}
          onChange={handleScanImageFile}
        />

        {cameraLoading && (
          <View style={[StyleSheet.absoluteFillObject, { backgroundColor: 'rgba(15, 23, 42, 0.75)', justifyContent: 'center', alignItems: 'center' }]}>
            <ActivityIndicator size="large" color="#10b981" />
            <Text style={{ color: '#94a3b8', fontSize: 11, marginTop: 8, fontWeight: '600' }}>Starting camera feed...</Text>
          </View>
        )}
      </View>
    );
  }

  // Native Mobile (Android & iOS)
  if (cameraPermission?.granted) {
    return (
      <View style={{ width: '100%', height: '100%', position: 'relative', overflow: 'hidden' }}>
        <CameraView
          style={{ width: '100%', height: '100%', position: 'absolute', top: 0, left: 0, right: 0, bottom: 0 }}
          facing={facingMode === 'user' ? 'front' : 'back'}
          barcodeScannerSettings={{
            barcodeTypes: ['qr'],
          }}
          onBarcodeScanned={isLocked ? undefined : ({ data }) => {
            onScan(data);
          }}
        />
        {/* Flip Camera Control on Mobile */}
        <TouchableOpacity
          style={{
            position: 'absolute',
            bottom: 8,
            right: 8,
            backgroundColor: 'rgba(15, 23, 42, 0.85)',
            paddingHorizontal: 8,
            paddingVertical: 4,
            borderRadius: 6,
            borderWidth: 1,
            borderColor: '#38bdf8',
            zIndex: 10,
          }}
          onPress={() => {
            setFacingMode(prev => prev === 'environment' ? 'user' : 'environment');
          }}
        >
          <Text style={{ color: '#38bdf8', fontSize: 10, fontWeight: 'bold' }}>
            🔄 {facingMode === 'environment' ? 'Front Cam' : 'Back Cam'}
          </Text>
        </TouchableOpacity>
      </View>
    );
  }

  return (
    <View style={{ padding: 14, alignItems: 'center', justifyContent: 'center', width: '100%', height: '100%', backgroundColor: '#0f172a' }}>
      <Text style={{ fontSize: 32, marginBottom: 4 }}>📷</Text>
      <Text style={{ color: '#ffffff', fontSize: 13, fontWeight: 'bold', textAlign: 'center', marginBottom: 4 }}>
        Camera Permission Needed
      </Text>
      <Text style={{ color: '#94a3b8', fontSize: 11, textAlign: 'center', marginBottom: 10 }}>
        Enable device camera to scan real-world QR codes instantly
      </Text>
      <TouchableOpacity
        style={{
          backgroundColor: '#10b981',
          paddingHorizontal: 14,
          paddingVertical: 8,
          borderRadius: 8,
        }}
        onPress={async () => {
          if (requestCameraPermission) {
            await requestCameraPermission();
          }
        }}
      >
        <Text style={{ color: '#022c22', fontSize: 12.5, fontWeight: '900' }}>📷 Enable Camera</Text>
      </TouchableOpacity>
    </View>
  );
}

