const calculateDLS = (
  firstInningsTotal,
  maxOvers,
  secondInningsRuns,
  secondInningsWkts,
  secondInningsBalls,
  team1Name,
  team2Name,
  currentInnings
) => {
  const totalOv = maxOvers || 20;
  const minOversRequired = totalOv <= 20 ? Math.min(5, Math.max(2, Math.floor(totalOv * 0.25))) : 20;
  const minBallsRequired = minOversRequired * 6;

  // 1. Check eligibility
  if (currentInnings !== 2) {
    const ovStr = `${Math.floor(secondInningsBalls / 6)}.${secondInningsBalls % 6}`;
    return {
      isApplicable: false,
      reason: `Match is in 1st Innings (${ovStr} ov). DLS requires the 2nd Innings to reach at least ${minOversRequired}.0 overs.`,
      minOversRequired,
      minBallsRequired,
      parScore: null,
      winner: null,
      margin: 0,
      verdictText: 'No Result (Match Abandoned in 1st Innings)',
    };
  }

  if (secondInningsBalls < minBallsRequired) {
    const ballsShort = minBallsRequired - secondInningsBalls;
    const ovStr = `${Math.floor(secondInningsBalls / 6)}.${secondInningsBalls % 6}`;
    return {
      isApplicable: false,
      reason: `Only ${ovStr} overs bowled in 2nd Innings. Minimum ${minOversRequired}.0 overs (${minBallsRequired} balls) required for a valid DLS result (${ballsShort} balls short).`,
      minOversRequired,
      minBallsRequired,
      parScore: null,
      winner: null,
      margin: 0,
      verdictText: `No Result (Minimum ${minOversRequired}.0 overs not reached in 2nd Innings)`,
    };
  }

  // 2. DLS Par Score Calculation
  const oversBowled = secondInningsBalls / 6;
  const fractionCompleted = Math.min(1.0, oversBowled / totalOv);

  // Wicket resource loss factor (0 to 10 wickets)
  const wicketPenaltyFactors = [1.0, 0.934, 0.851, 0.749, 0.627, 0.490, 0.349, 0.220, 0.119, 0.047, 0.0];
  const wktIndex = Math.min(10, Math.max(0, secondInningsWkts));
  const wktWeight = wicketPenaltyFactors[wktIndex];

  // Fraction of resource used by chasing team
  const resourceRemainingFraction = Math.pow(Math.max(0, 1 - fractionCompleted), 1.12) * wktWeight;
  const resourceUsedFraction = Math.max(0.05, Math.min(1.0, 1.0 - resourceRemainingFraction));

  const targetBase = Math.max(1, firstInningsTotal || 184);
  const parScore = Math.floor(targetBase * resourceUsedFraction);

  let winner = null;
  let margin = 0;
  let verdictText = '';

  if (secondInningsRuns > parScore) {
    winner = team2Name;
    margin = secondInningsRuns - parScore;
    verdictText = `🎉 ${team2Name} won by ${margin} run${margin === 1 ? '' : 's'} (DLS Method)`;
  } else if (secondInningsRuns < parScore) {
    winner = team1Name;
    margin = parScore - secondInningsRuns;
    verdictText = `🏆 ${team1Name} won by ${margin} run${margin === 1 ? '' : 's'} (DLS Method)`;
  } else {
    verdictText = `🤝 Match Tied (DLS Method - Scores Level at ${parScore})`;
  }

  return {
    isApplicable: true,
    minOversRequired,
    minBallsRequired,
    oversBowledStr: `${Math.floor(secondInningsBalls / 6)}.${secondInningsBalls % 6}`,
    parScore,
    currentScore: secondInningsRuns,
    currentWkts: secondInningsWkts,
    firstInningsTotal: targetBase,
    winner,
    margin,
    verdictText,
    isAhead: secondInningsRuns > parScore,
    diff: Math.abs(secondInningsRuns - parScore),
  };
};


