function getDLSResourcePercentage(oversLeft, wktsLost, maxMatchOvers = 20) {
  if (wktsLost >= 10 || oversLeft <= 0) return 0;
  const wkt = Math.max(0, Math.min(9, Math.floor(wktsLost)));
  const cappedOvers = Math.max(0, Math.min(oversLeft, maxMatchOvers));

  if (maxMatchOvers <= 20) {
    const ovFloor = Math.floor(cappedOvers);
    const ovCeil = Math.min(20, Math.ceil(cappedOvers));
    const fraction = cappedOvers - ovFloor;
    const rFloor = DLS_RESOURCE_TABLE_T20[ovFloor]?.[wkt] || 0;
    const rCeil = DLS_RESOURCE_TABLE_T20[ovCeil]?.[wkt] || 0;
    return rFloor + fraction * (rCeil - rFloor);
  } else {
    const wktFactors = [1.0, 0.934, 0.851, 0.749, 0.627, 0.490, 0.349, 0.220, 0.119, 0.047];
    const b = 0.035;
    const baseR = 100 * (1 - Math.exp(-b * cappedOvers));
    return baseR * (wktFactors[wkt] || 0);
  }
}

function getReducedBowlerQuota(overs) {
  const totalOv = Math.max(1, Number(overs) || 20);
  const baseQuota = Math.floor(totalOv / 5);
  const remainder = totalOv % 5;
  const maxBowlerQuota = remainder > 0 ? baseQuota + 1 : baseQuota;
  const bowlersWithMaxQuota = remainder;
  const quotaText = remainder > 0
    ? `Max ${remainder} bowler${remainder > 1 ? 's' : ''} can bowl ${maxBowlerQuota} ov, others max ${baseQuota} ov`
    : `Max ${baseQuota} overs per bowler`;
  return {
    baseQuota,
    maxBowlerQuota,
    bowlersWithMaxQuota,
    quotaText,
  };
}

function calculateDLSTarget({
  firstInnRuns = 0,
  firstInnWkts = 0,
  firstInnBalls = 0,
  origMaxOvers = 20,
  revisedOvers = 12,
  interruptionMode = 'terminate_inn1', // 'terminate_inn1' | 'curtail_both' | 'curtail_inn2'
  secondInnRuns = 0,
  secondInnWkts = 0,
  secondInnBalls = 0,
}) {
  const safeOrigOvers = Math.max(1, Number(origMaxOvers) || 20);
  const safeRevisedOvers = Math.max(1, Math.min(safeOrigOvers, Number(revisedOvers) || 12));
  const G = safeOrigOvers <= 20 ? 160 : 245;
  const firstInnOversBowled = (Number(firstInnBalls) || 0) / 6;

  let r1 = 100.0;
  let r2 = 100.0;

  if (interruptionMode === 'terminate_inn1') {
    if (firstInnWkts >= 10) {
      r1 = 100.0;
    } else {
      const oversLeftAtInterruption = Math.max(0, safeOrigOvers - firstInnOversBowled);
      const lostResource = getDLSResourcePercentage(oversLeftAtInterruption, firstInnWkts, safeOrigOvers);
      r1 = Math.max(1.0, 100.0 - lostResource);
    }
    r2 = getDLSResourcePercentage(safeRevisedOvers, 0, safeOrigOvers);
  } else if (interruptionMode === 'curtail_both') {
    const oversLeftBefore = Math.max(0, safeOrigOvers - firstInnOversBowled);
    const oversLeftAfter = Math.max(0, safeRevisedOvers - firstInnOversBowled);
    const rBefore = getDLSResourcePercentage(oversLeftBefore, firstInnWkts, safeOrigOvers);
    const rAfter = getDLSResourcePercentage(oversLeftAfter, firstInnWkts, safeOrigOvers);
    const lostResource = Math.max(0, rBefore - rAfter);
    r1 = Math.max(1.0, 100.0 - lostResource);
    r2 = getDLSResourcePercentage(safeRevisedOvers, 0, safeOrigOvers);
  } else if (interruptionMode === 'curtail_inn2') {
    r1 = 100.0;
    const secondInnOversBowled = (Number(secondInnBalls) || 0) / 6;
    const oversLeftBefore = Math.max(0, safeOrigOvers - secondInnOversBowled);
    const oversLeftAfter = Math.max(0, safeRevisedOvers - secondInnOversBowled);
    const rBefore = getDLSResourcePercentage(oversLeftBefore, secondInnWkts, safeOrigOvers);
    const rAfter = getDLSResourcePercentage(oversLeftAfter, secondInnWkts, safeOrigOvers);
    const lostResource = Math.max(0, rBefore - rAfter);
    r2 = Math.max(1.0, 100.0 - lostResource);
  }

  let revisedTarget = 0;
  let formulaType = '';
  if (r2 <= r1) {
    revisedTarget = Math.floor((Number(firstInnRuns) || 0) * (r2 / r1)) + 1;
    formulaType = 'proportional';
  } else {
    revisedTarget = Math.floor((Number(firstInnRuns) || 0) + (r2 - r1) * (G / 100.0)) + 1;
    formulaType = 'surplus';
  }

  const parScore = Math.max(0, revisedTarget - 1);
  const rrr = safeRevisedOvers > 0 ? (revisedTarget / safeRevisedOvers).toFixed(2) : '0.00';
  const bowlerQuota = getReducedBowlerQuota(safeRevisedOvers);

  return {
    revisedTarget,
    parScore,
    r1: Number(r1.toFixed(1)),
    r2: Number(r2.toFixed(1)),
    revisedOvers: safeRevisedOvers,
    rrr,
    formulaType,
    bowlerQuota,
  };
}


// ============================================================================
// ICC-STANDARD MATCH AWARDS & MVP (MOST VALUABLE PLAYER) ENGINE
// Computes Player of the Match, Best Batter, Best Bowler, and MVP Leaderboard
// ============================================================================
function calculateMatchAwardsAndMVP(matchData, liveDataInnings1 = null, liveDataInnings2 = null) {
  if (!matchData) return null;

  const inn1 = matchData.innings1 || {};
  const inn2 = matchData.innings2 || {};
  const mLive = matchData.liveState || {};

  // 1. Resolve Innings 1 Batting
  let inn1Batting = [];
  if (Array.isArray(liveDataInnings1?.batting) && liveDataInnings1.batting.length > 0) {
    inn1Batting = liveDataInnings1.batting;
  } else if (Array.isArray(inn1.batting) && inn1.batting.some(b => (b.runs || 0) > 0 || (b.balls || 0) > 0)) {
    inn1Batting = inn1.batting;
  } else if (Array.isArray(mLive.firstInningsSummary?.batting) && mLive.firstInningsSummary.batting.length > 0) {
    inn1Batting = mLive.firstInningsSummary.batting;
  } else if (mLive.liveBatters && (mLive.currentInnings === 1 || !mLive.firstInningsSummary)) {
    inn1Batting = Object.keys(mLive?.liveBatters || {}).map(name => ({
      name,
      ...mLive.liveBatters[name],
    }));
  } else if (Array.isArray(inn1.batting)) {
    inn1Batting = inn1.batting;
  }

  // 2. Resolve Innings 1 Bowling
  let inn1Bowling = [];
  if (Array.isArray(liveDataInnings1?.bowling) && liveDataInnings1.bowling.length > 0) {
    inn1Bowling = liveDataInnings1.bowling;
  } else if (Array.isArray(inn1.bowling) && inn1.bowling.some(bw => (bw.runs || 0) > 0 || (bw.wickets || 0) > 0 || (bw.balls || 0) > 0)) {
    inn1Bowling = inn1.bowling;
  } else if (Array.isArray(mLive.firstInningsSummary?.bowling) && mLive.firstInningsSummary.bowling.length > 0) {
    inn1Bowling = mLive.firstInningsSummary.bowling;
  } else if (mLive.liveBowlerStats && (mLive.currentInnings === 1 || !mLive.firstInningsSummary)) {
    inn1Bowling = Object.keys(mLive?.liveBowlerStats || {}).map(name => {
      const bw = mLive.liveBowlerStats[name];
      const balls = bw.balls || 0;
      return {
        name,
        ...bw,
        overs: `${Math.floor(balls / 6)}.${balls % 6}`,
        econ: balls > 0 ? ((bw.runs / balls) * 6).toFixed(2) : '0.00',
      };
    });
  } else if (Array.isArray(inn1.bowling)) {
    inn1Bowling = inn1.bowling;
  }

  // 3. Resolve Innings 2 Batting
  let inn2Batting = [];
  if (Array.isArray(liveDataInnings2?.batting) && liveDataInnings2.batting.length > 0) {
    inn2Batting = liveDataInnings2.batting;
  } else if (Array.isArray(inn2.batting) && inn2.batting.some(b => (b.runs || 0) > 0 || (b.balls || 0) > 0)) {
    inn2Batting = inn2.batting;
  } else if (mLive.liveBatters && mLive.currentInnings === 2) {
    inn2Batting = Object.keys(mLive?.liveBatters || {}).map(name => ({
      name,
      ...mLive.liveBatters[name],
    }));
  } else if (Array.isArray(inn2.batting)) {
    inn2Batting = inn2.batting;
  }

  // 4. Resolve Innings 2 Bowling
  let inn2Bowling = [];
  if (Array.isArray(liveDataInnings2?.bowling) && liveDataInnings2.bowling.length > 0) {
    inn2Bowling = liveDataInnings2.bowling;
  } else if (Array.isArray(inn2.bowling) && inn2.bowling.some(bw => (bw.runs || 0) > 0 || (bw.wickets || 0) > 0 || (bw.balls || 0) > 0)) {
    inn2Bowling = inn2.bowling;
  } else if (mLive.liveBowlerStats && mLive.currentInnings === 2) {
    inn2Bowling = Object.keys(mLive?.liveBowlerStats || {}).map(name => {
      const bw = mLive.liveBowlerStats[name];
      const balls = bw.balls || 0;
      return {
        name,
        ...bw,
        overs: `${Math.floor(balls / 6)}.${balls % 6}`,
        econ: balls > 0 ? ((bw.runs / balls) * 6).toFixed(2) : '0.00',
      };
    });
  } else if (Array.isArray(inn2.bowling)) {
    inn2Bowling = inn2.bowling;
  }

  const inn1Team = inn1.team || matchData.teamA || 'Team 1';
  const inn2Team = inn2.team || matchData.teamB || 'Team 2';

  const playersMap = {};

  const getOrCreatePlayer = (rawName, team) => {
    if (!rawName) return null;
    const cleanName = String(rawName).replace(/\s*\([^)]*\)/g, '').trim();
    if (!cleanName) return null;
    if (!playersMap[cleanName]) {
      playersMap[cleanName] = {
        name: cleanName,
        fullName: rawName,
        team: team || 'Player',
        runs: 0,
        balls: 0,
        fours: 0,
        sixes: 0,
        sr: '0.0',
        isNotOut: false,
        didBat: false,
        wickets: 0,
        overs: '0.0',
        oversNum: 0,
        maidens: 0,
        runsConceded: 0,
        econ: '0.0',
        dots: 0,
        didBowl: false,
        catches: 0,
        stumpings: 0,
        runOuts: 0,
        battingPts: 0,
        bowlingPts: 0,
        fieldingPts: 0,
        totalMvpPts: 0,
      };
    }
    return playersMap[cleanName];
  };

  // 1. Process 1st Innings Batting
  inn1Batting.forEach(b => {
    const p = getOrCreatePlayer(b.name, inn1Team);
    if (!p) return;
    p.didBat = true;
    p.runs += Number(b.runs || 0);
    p.balls += Number(b.balls || 0);
    p.fours += Number(b.fours || 0);
    p.sixes += Number(b.sixes || 0);
    p.isNotOut = Boolean(b.isNotOut);
    p.sr = b.sr || (p.balls > 0 ? ((p.runs / p.balls) * 100).toFixed(1) : '0.0');

    if (b.dismissal) {
      const dis = String(b.dismissal);
      const catchMatch = dis.match(/c\s+([A-Za-z\s]+?)\s+b\s+/i);
      if (catchMatch && catchMatch[1]) {
        const fName = catchMatch[1].trim();
        if (fName && fName.toLowerCase() !== 'sub' && fName.toLowerCase() !== '&') {
          const fielder = getOrCreatePlayer(fName, inn2Team);
          if (fielder) fielder.catches += 1;
        }
      } else if (dis.toLowerCase().includes('c & b') || dis.toLowerCase().includes('c&b')) {
        const bowlerMatch = dis.match(/b\s+([A-Za-z\s]+)/i);
        if (bowlerMatch && bowlerMatch[1]) {
          const fielder = getOrCreatePlayer(bowlerMatch[1].trim(), inn2Team);
          if (fielder) fielder.catches += 1;
        }
      }
      const stMatch = dis.match(/st\s+([A-Za-z\s]+?)\s+b\s+/i);
      if (stMatch && stMatch[1]) {
        const fielder = getOrCreatePlayer(stMatch[1].trim(), inn2Team);
        if (fielder) fielder.stumpings += 1;
      }
      const roMatch = dis.match(/run out\s*\(([^)]+)\)/i);
      if (roMatch && roMatch[1]) {
        const roNames = roMatch[1].split(/[\/,+]/);
        roNames.forEach(rn => {
          const cleanFielder = rn.trim();
          if (cleanFielder) {
            const fielder = getOrCreatePlayer(cleanFielder, inn2Team);
            if (fielder) fielder.runOuts += 1;
          }
        });
      }
    }
  });

  // 2. Process 1st Innings Bowling
  inn1Bowling.forEach(bw => {
    const p = getOrCreatePlayer(bw.name, inn2Team);
    if (!p) return;
    p.didBowl = true;
    p.wickets += Number(bw.wickets || 0);
    const ovParts = String(bw.overs || '0.0').split('.');
    const ovNum = (parseInt(ovParts[0] || '0', 10)) + (parseInt(ovParts[1] || '0', 10) / 6);
    p.oversNum += ovNum;
    p.overs = String(bw.overs || '0.0');
    p.maidens += Number(bw.maidens || 0);
    p.runsConceded += Number(bw.runs || 0);
    p.econ = bw.econ || (p.oversNum > 0 ? (p.runsConceded / p.oversNum).toFixed(1) : '0.0');
    p.dots += Number(bw.dots || (ovNum >= 1 ? Math.floor(ovNum * 2.5) : 0));
  });

  // 3. Process 2nd Innings Batting
  inn2Batting.forEach(b => {
    const p = getOrCreatePlayer(b.name, inn2Team);
    if (!p) return;
    p.didBat = true;
    p.runs += Number(b.runs || 0);
    p.balls += Number(b.balls || 0);
    p.fours += Number(b.fours || 0);
    p.sixes += Number(b.sixes || 0);
    p.isNotOut = Boolean(b.isNotOut);
    p.sr = b.sr || (p.balls > 0 ? ((p.runs / p.balls) * 100).toFixed(1) : '0.0');

    if (b.dismissal) {
      const dis = String(b.dismissal);
      const catchMatch = dis.match(/c\s+([A-Za-z\s]+?)\s+b\s+/i);
      if (catchMatch && catchMatch[1]) {
        const fName = catchMatch[1].trim();
        if (fName && fName.toLowerCase() !== 'sub' && fName.toLowerCase() !== '&') {
          const fielder = getOrCreatePlayer(fName, inn1Team);
          if (fielder) fielder.catches += 1;
        }
      } else if (dis.toLowerCase().includes('c & b') || dis.toLowerCase().includes('c&b')) {
        const bowlerMatch = dis.match(/b\s+([A-Za-z\s]+)/i);
        if (bowlerMatch && bowlerMatch[1]) {
          const fielder = getOrCreatePlayer(bowlerMatch[1].trim(), inn1Team);
          if (fielder) fielder.catches += 1;
        }
      }
      const stMatch = dis.match(/st\s+([A-Za-z\s]+?)\s+b\s+/i);
      if (stMatch && stMatch[1]) {
        const fielder = getOrCreatePlayer(stMatch[1].trim(), inn1Team);
        if (fielder) fielder.stumpings += 1;
      }
      const roMatch = dis.match(/run out\s*\(([^)]+)\)/i);
      if (roMatch && roMatch[1]) {
        const roNames = roMatch[1].split(/[\/,+]/);
        roNames.forEach(rn => {
          const cleanFielder = rn.trim();
          if (cleanFielder) {
            const fielder = getOrCreatePlayer(cleanFielder, inn1Team);
            if (fielder) fielder.runOuts += 1;
          }
        });
      }
    }
  });

  // 4. Process 2nd Innings Bowling
  inn2Bowling.forEach(bw => {
    const p = getOrCreatePlayer(bw.name, inn1Team);
    if (!p) return;
    p.didBowl = true;
    p.wickets += Number(bw.wickets || 0);
    const ovParts = String(bw.overs || '0.0').split('.');
    const ovNum = (parseInt(ovParts[0] || '0', 10)) + (parseInt(ovParts[1] || '0', 10) / 6);
    p.oversNum += ovNum;
    p.overs = String(bw.overs || '0.0');
    p.maidens += Number(bw.maidens || 0);
    p.runsConceded += Number(bw.runs || 0);
    p.econ = bw.econ || (p.oversNum > 0 ? (p.runsConceded / p.oversNum).toFixed(1) : '0.0');
    p.dots += Number(bw.dots || (ovNum >= 1 ? Math.floor(ovNum * 2.5) : 0));
  });

  const playerList = Object.values(playersMap);

  playerList.forEach(p => {
    let batPts = p.runs * 1;
    batPts += p.fours * 1;
    batPts += p.sixes * 2;
    if (p.runs >= 100) batPts += 20;
    else if (p.runs >= 50) batPts += 10;
    else if (p.runs >= 30) batPts += 4;

    const srNum = parseFloat(p.sr || '0');
    if (p.balls >= 10) {
      if (srNum >= 175) batPts += 8;
      else if (srNum >= 140) batPts += 4;
      else if (srNum < 80) batPts -= 4;
    }
    p.battingPts = Math.round(batPts * 10) / 10;

    let bowlPts = p.wickets * 25;
    if (p.wickets >= 5) bowlPts += 30;
    else if (p.wickets >= 3) bowlPts += 15;
    bowlPts += p.maidens * 10;
    bowlPts += p.dots * 1;

    const econNum = parseFloat(p.econ || '0');
    if (p.oversNum >= 2.0) {
      if (econNum <= 5.5) bowlPts += 8;
      else if (econNum <= 7.0) bowlPts += 4;
      else if (econNum > 11.0) bowlPts -= 6;
    }
    p.bowlingPts = Math.round(bowlPts * 10) / 10;

    let fldPts = (p.catches * 10) + (p.stumpings * 12) + (p.runOuts * 15);
    p.fieldingPts = fldPts;

    p.totalMvpPts = Math.round((p.battingPts + p.bowlingPts + p.fieldingPts) * 10) / 10;
  });

  const mvpLeaderboard = [...playerList].sort((a, b) => b.totalMvpPts - a.totalMvpPts);

  const battersList = playerList
    .filter(p => p.didBat && (p.runs > 0 || p.balls > 0))
    .sort((a, b) => {
      if (b.runs !== a.runs) return b.runs - a.runs;
      return parseFloat(b.sr || 0) - parseFloat(a.sr || 0);
    });
  const bestBatter = battersList[0] || null;

  const bowlersList = playerList
    .filter(p => p.didBowl && p.oversNum > 0)
    .sort((a, b) => {
      if (b.wickets !== a.wickets) return b.wickets - a.wickets;
      return parseFloat(a.econ || 99) - parseFloat(b.econ || 99);
    });
  const bestBowler = bowlersList[0] || null;

  const pomPlayer = mvpLeaderboard[0] || null;
  let pomSummary = '';
  if (pomPlayer) {
    const parts = [];
    if (pomPlayer.runs > 0) parts.push(`${pomPlayer.runs} runs (${pomPlayer.balls}b)`);
    if (pomPlayer.wickets > 0) parts.push(`${pomPlayer.wickets}/${pomPlayer.runsConceded} (${pomPlayer.overs} ov)`);
    if (pomPlayer.catches > 0) parts.push(`${pomPlayer.catches} ct`);
    if (pomPlayer.stumpings > 0) parts.push(`${pomPlayer.stumpings} st`);
    if (pomPlayer.runOuts > 0) parts.push(`${pomPlayer.runOuts} ro`);
    const statStr = (parts || []).length > 0 ? ` (${parts.join(', ')})` : '';
    pomSummary = `${pomPlayer.name}${statStr}`;
  }

  return {
    pom: pomSummary || (matchData.pom ? matchData.pom : (pomPlayer ? pomPlayer.name : 'Match MVP')),
    pomPlayer,
    bestBatter,
    bestBowler,
    mvpLeaderboard: mvpLeaderboard.slice(0, 10),
  };
}

const getResponsiveBadgePos = (wheelDimension, angleDegrees, badgeW, badgeH) => {
  const center = wheelDimension / 2;
  const radius = wheelDimension * 0.31;
  const radians = (angleDegrees * Math.PI) / 180;
  const x = center + radius * Math.sin(radians);
  const y = center - radius * Math.cos(radians);
  return {
    left: Math.round(x - badgeW / 2),
    top: Math.round(y - badgeH / 2),
  };
};

