// REALISTIC 3D CRICKET LEATHER BALL COMPONENT
// ============================================================================
const RealisticCricketLeatherBall = ({ size = 14, style = {} }) => {
  const ballSize = size;
  const radius = ballSize / 2;
  const shineSize = Math.max(3, ballSize * 0.35);

  return (
    <View
      style={[
        {
          width: ballSize,
          height: ballSize,
          borderRadius: radius,
          backgroundColor: '#dc2626', // Vibrant 3D cricket red leather
          borderWidth: 0.7,
          borderColor: '#7f1d1d',
          position: 'relative',
          overflow: 'hidden',
          justifyContent: 'center',
          alignItems: 'center',
          shadowColor: '#ef4444',
          shadowOffset: { width: 0, height: 1 },
          shadowOpacity: 0.5,
          shadowRadius: 2,
          elevation: 2,
        },
        style,
      ]}
    >
      {/* 3D Depth Shadow (Bottom-Right) */}
      <View
        style={{
          position: 'absolute',
          bottom: -1,
          right: -1,
          width: ballSize * 0.85,
          height: ballSize * 0.85,
          borderRadius: (ballSize * 0.85) / 2,
          backgroundColor: '#450a0a',
          opacity: 0.65,
        }}
      />

      {/* Cricket Stitched White/Cream Seam */}
      <View
        style={{
          position: 'absolute',
          width: ballSize * 1.35,
          height: 1.5,
          backgroundColor: '#fef08a', // Cream stitched seam
          borderWidth: 0.4,
          borderColor: '#ffffff',
          borderStyle: 'dashed',
          transform: [{ rotate: '-35deg' }],
          opacity: 0.95,
        }}
      />

      {/* 3D Specular Highlight / Shine Reflection */}
      <View
        style={{
          position: 'absolute',
          top: 1.2,
          left: 1.8,
          width: shineSize,
          height: shineSize,
          borderRadius: shineSize / 2,
          backgroundColor: '#ffffff',
          opacity: 0.7,
        }}
      />
    </View>
  );
};

