// ============================================================================
// COMPREHENSIVE TEAM LOGO RESOLVER (CHECKS DIRECT PROPS, REGISTERED TEAMS, & USERS DB)
// ============================================================================
function resolveTeamLogo(team, allTeams = [], allUsers = []) {
  if (!team) return null;
  const isGoodUri = (val) => {
    return Boolean(
      val &&
      typeof val === 'string' &&
      val !== 'null' &&
      val !== 'undefined' &&
      val.trim().length > 0 &&
      (val.startsWith('http') || val.startsWith('data:') || val.startsWith('file:') || val.startsWith('blob:') || val.startsWith('content:'))
    );
  };

  // 1. Direct property on team object
  const candidates = [
    team.logo,
    team.logoUri,
    team.logoUrl,
    team.customLogoUrl,
    team.photo,
    team.photoUri,
    team.avatar,
    team.avatarUri,
    team.image,
    team.imageUri,
  ];
  for (const c of candidates) {
    if (isGoodUri(c)) return c.trim();
  }

  // 2. Lookup in all registered teams by ID or name
  const teamName = String(team.name || '').trim().toLowerCase();
  const teamId = team.id ? String(team.id).trim().toLowerCase() : '';
  if (Array.isArray(allTeams) && (teamName || teamId)) {
    const match = allTeams.find(t => t && ((teamId && String(t.id).toLowerCase() === teamId) || (teamName && String(t.name || '').trim().toLowerCase() === teamName)));
    if (match && match !== team) {
      const matchCandidates = [
        match.logo,
        match.logoUri,
        match.logoUrl,
        match.customLogoUrl,
        match.photo,
        match.photoUri,
        match.avatar,
        match.avatarUri,
        match.image,
        match.imageUri,
      ];
      for (const c of matchCandidates) {
        if (isGoodUri(c)) return c.trim();
      }
    }
  }

  // 3. Lookup in all users' createdTeams (usersDb)
  if (Array.isArray(allUsers) && teamName) {
    for (const u of allUsers) {
      if (u && Array.isArray(u.createdTeams)) {
        const uTeam = u.createdTeams.find(t => t && String(t.name || '').trim().toLowerCase() === teamName);
        if (uTeam) {
          const uCandidates = [uTeam.logo, uTeam.logoUri, uTeam.customLogoUrl, uTeam.photo];
          for (const c of uCandidates) {
            if (isGoodUri(c)) return c.trim();
          }
        }
      }
    }
  }

  return null;
}

// ============================================================================
// SMART TEAM LOGO COMPONENT (FAIL-SAFE IMAGE RENDERING WITH AUTOMATIC FLAG FALLBACK)
// ============================================================================
function SmartTeamLogo({ team, allTeams = [], allUsers = [], style, flagStyle, fallbackFlag = '🦁' }) {
  const [hasError, setHasError] = useState(false);
  const localLogo = getDashTeamLogo(team?.name) || getDashTeamLogo(team?.shortName);
  const logoUri = resolveTeamLogo(team, allTeams, allUsers);

  useEffect(() => {
    setHasError(false);
  }, [logoUri]);

  if (localLogo) {
    return (
      <Image
        source={localLogo}
        style={style}
        resizeMode="contain"
      />
    );
  }

  if (logoUri && !hasError) {
    return (
      <Image
        source={{ uri: logoUri }}
        style={style}
        resizeMode="cover"
        onError={() => setHasError(true)}
      />
    );
  }

  return <Text style={flagStyle}>{team?.flag || fallbackFlag}</Text>;
}

// ============================================================================
// STYLISH CROSS-PLATFORM TEAM BADGE PILL (CLEAN REPLACEMENT FOR BROKEN WINDOWS EMOJI FLAGS)
// ============================================================================
function TeamFlagBadge({ flag, logo, shortName, fullName, isBatting, theme, size = 'md' }) {
  const [imageError, setImageError] = useState(false);
  const isSmall = size === 'sm';
  const isLg = size === 'lg';
  const dim = isSmall ? 28 : (isLg ? 42 : 36);
  const radius = isSmall ? 5 : (isLg ? 8 : 7);
  const borderColor = isBatting ? (theme?.primary || '#10b981') : (theme?.secondary || '#38bdf8');
  const bgColor = isBatting ? 'rgba(16, 185, 129, 0.15)' : 'rgba(56, 189, 248, 0.15)';

  useEffect(() => {
    setImageError(false);
  }, [logo]);

  // 1. Priority 1: User-Uploaded Custom Team Logo (Image URI / URL)
  if (!imageError && logo && typeof logo === 'string' && (logo.startsWith('http') || logo.startsWith('data:') || logo.startsWith('file:') || logo.startsWith('blob:') || logo.startsWith('content:'))) {
    return (
      <View
        style={{
          width: dim,
          height: dim,
          borderRadius: radius,
          overflow: 'hidden',
          backgroundColor: '#0f172a',
          borderWidth: 1.5,
          borderColor: borderColor,
          justifyContent: 'center',
          alignItems: 'center',
          shadowColor: '#000',
          shadowOffset: { width: 0, height: 1 },
          shadowOpacity: 0.3,
          shadowRadius: 3,
          elevation: 2,
        }}
      >
        <Image
          source={{ uri: logo }}
          style={{ width: '100%', height: '100%' }}
          resizeMode="cover"
          onError={() => setImageError(true)}
        />
      </View>
    );
  }

  // 2. Priority 2: Local Bundled Tournament Team Logo / 20 Preset Crests
  const localLogo = getDashTeamLogo(fullName) || getDashTeamLogo(shortName) || getRandomCrestForTeam(fullName || shortName);
  if (localLogo) {
    return (
      <View
        style={{
          width: dim,
          height: dim,
          borderRadius: radius,
          overflow: 'hidden',
          backgroundColor: '#0f172a',
          borderWidth: 1.5,
          borderColor: borderColor,
          justifyContent: 'center',
          alignItems: 'center',
          shadowColor: '#000',
          shadowOffset: { width: 0, height: 1 },
          shadowOpacity: 0.3,
          shadowRadius: 3,
          elevation: 2,
        }}
      >
        <Image
          source={localLogo}
          style={{ width: '92%', height: '92%' }}
          resizeMode="contain"
        />
      </View>
    );
  }

  // 3. Priority 3: Custom Mascot / Team Flag Emoji (fallback)
  const effectiveFlag = flag && String(flag).trim() ? String(flag).trim() : (isBatting ? '🦁' : '⚡');

  return (
    <View
      style={{
        width: dim,
        height: dim,
        borderRadius: radius,
        backgroundColor: bgColor,
        borderWidth: 1.2,
        borderColor: borderColor,
        justifyContent: 'center',
        alignItems: 'center',
        shadowColor: borderColor,
        shadowOffset: { width: 0, height: 1 },
        shadowOpacity: 0.25,
        shadowRadius: 3,
        elevation: 2,
      }}
    >
      <Text style={{ fontSize: isSmall ? 16 : 20 }}>{effectiveFlag}</Text>
    </View>
  );
}

// 1. CLEAN BOWLED (3D Cricket Ball Crashing into Stumps, Flying Stumps, Spinning Bails, Radial Shockwave Sparks)
function BowledGraphic({ loopAnim, spinAnim, glowAnim }) {
  const leftStumpRotate = loopAnim.interpolate({ inputRange: [0, 0.45, 1], outputRange: ['-10deg', '-32deg', '-14deg'] });
  const middleStumpTranslateY = loopAnim.interpolate({ inputRange: [0, 0.45, 1], outputRange: [-8, -55, -16] });
  const middleStumpRotate = loopAnim.interpolate({ inputRange: [0, 0.45, 1], outputRange: ['15deg', '75deg', '38deg'] });
  const rightStumpTranslateX = loopAnim.interpolate({ inputRange: [0, 0.45, 1], outputRange: [4, 34, 12] });
  const rightStumpRotate = loopAnim.interpolate({ inputRange: [0, 0.45, 1], outputRange: ['15deg', '48deg', '25deg'] });

  const leftBailTranslateX = loopAnim.interpolate({ inputRange: [0, 0.45, 1], outputRange: [-12, -62, -22] });
  const leftBailTranslateY = loopAnim.interpolate({ inputRange: [0, 0.45, 1], outputRange: [-15, -74, -28] });
  const leftBailRotate = spinAnim.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '-720deg'] });

  const rightBailTranslateX = loopAnim.interpolate({ inputRange: [0, 0.45, 1], outputRange: [12, 65, 24] });
  const rightBailTranslateY = loopAnim.interpolate({ inputRange: [0, 0.45, 1], outputRange: [-14, -68, -25] });
  const rightBailRotate = spinAnim.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '720deg'] });

  const sparkScale = glowAnim.interpolate({ inputRange: [0.4, 1], outputRange: [0.85, 1.45] });

  return (
    <View style={{ width: 170, height: 130, justifyContent: 'center', alignItems: 'center', marginVertical: 4 }}>
      <Svg width="170" height="130" viewBox="0 0 170 130">
        <Rect x="20" y="112" width="130" height="8" rx="4" fill="#166534" />
        <Line x1="25" y1="112" x2="145" y2="112" stroke="#ffffff" strokeWidth="2" strokeDasharray="4,3" />
        <Line x1="85" y1="112" x2="85" y2="120" stroke="#ffffff" strokeWidth="2" />
      </Svg>

      {/* Pulsing Spark Shockwaves */}
      <Animated.View style={{ position: 'absolute', top: 48, transform: [{ scale: sparkScale }] }}>
        <Svg width="120" height="80" viewBox="0 0 120 80">
          <Circle cx="60" cy="40" r="26" fill="#ef4444" opacity="0.45" />
          <Line x1="60" y1="40" x2="20" y2="10" stroke="#fde047" strokeWidth="3.5" strokeLinecap="round" />
          <Line x1="60" y1="40" x2="100" y2="10" stroke="#fde047" strokeWidth="3.5" strokeLinecap="round" />
          <Line x1="60" y1="40" x2="60" y2="0" stroke="#fbbf24" strokeWidth="3" strokeLinecap="round" />
          <Line x1="60" y1="40" x2="10" y2="40" stroke="#f97316" strokeWidth="3" strokeLinecap="round" />
          <Line x1="60" y1="40" x2="110" y2="40" stroke="#f97316" strokeWidth="3" strokeLinecap="round" />
        </Svg>
      </Animated.View>

      {/* Off Stump (Tilted) */}
      <Animated.View style={{ position: 'absolute', bottom: 14, left: 56, width: 7, height: 68, backgroundColor: '#fef08a', borderRadius: 3.5, borderWidth: 1, borderColor: '#d97706', transform: [{ rotate: leftStumpRotate }] }} />
      {/* Middle Stump (Flying upward & rotating) */}
      <Animated.View style={{ position: 'absolute', bottom: 14, left: 81, width: 7, height: 68, backgroundColor: '#fef08a', borderRadius: 3.5, borderWidth: 1, borderColor: '#d97706', transform: [{ translateY: middleStumpTranslateY }, { rotate: middleStumpRotate }] }} />
      {/* Leg Stump (Flying right) */}
      <Animated.View style={{ position: 'absolute', bottom: 14, left: 106, width: 7, height: 68, backgroundColor: '#fef08a', borderRadius: 3.5, borderWidth: 1, borderColor: '#d97706', transform: [{ translateX: rightStumpTranslateX }, { rotate: rightStumpRotate }] }} />

      {/* Flying Left Bail */}
      <Animated.View style={{ position: 'absolute', top: 40, left: 62, width: 18, height: 4.5, backgroundColor: '#ffffff', borderRadius: 2, borderWidth: 1, borderColor: '#f59e0b', transform: [{ translateX: leftBailTranslateX }, { translateY: leftBailTranslateY }, { rotate: leftBailRotate }] }} />
      {/* Flying Right Bail */}
      <Animated.View style={{ position: 'absolute', top: 40, left: 88, width: 18, height: 4.5, backgroundColor: '#ffffff', borderRadius: 2, borderWidth: 1, borderColor: '#f59e0b', transform: [{ translateX: rightBailTranslateX }, { translateY: rightBailTranslateY }, { rotate: rightBailRotate }] }} />

      {/* 3D Realistic Cricket Leather Ball Crashing Directly into Stumps */}
      <Animated.View
        style={{
          position: 'absolute',
          top: 45,
          left: 55,
          transform: [
            {
              translateX: loopAnim.interpolate({
                inputRange: [0, 0.45, 1],
                outputRange: [-75, 26, -75],
              }),
            },
            {
              translateY: loopAnim.interpolate({
                inputRange: [0, 0.45, 1],
                outputRange: [28, -4, 28],
              }),
            },
            {
              rotate: spinAnim.interpolate({
                inputRange: [0, 1],
                outputRange: ['0deg', '720deg'],
              }),
            },
          ],
        }}
      >
        <RealisticCricketLeatherBall size={28} />
      </Animated.View>
    </View>
  );
}

// 2. CAUGHT (Swooping Ball Trajectory + Clamping Fielding Gloves & Star Burst)
function CaughtGraphic({ loopAnim, spinAnim, glowAnim }) {
  const ballTranslateX = loopAnim.interpolate({ inputRange: [0, 0.5, 1], outputRange: [-55, 0, -55] });
  const ballTranslateY = loopAnim.interpolate({ inputRange: [0, 0.25, 0.5, 0.75, 1], outputRange: [28, -26, 0, -26, 28] });
  const ballRotate = spinAnim.interpolate({ inputRange: [0, 1], outputRange: ['0deg', '360deg'] });
  const gloveScale = loopAnim.interpolate({ inputRange: [0, 0.45, 0.5, 0.7, 1], outputRange: [0.92, 1.28, 1.0, 1.0, 0.92] });
  const shockwaveScale = loopAnim.interpolate({ inputRange: [0, 0.5, 1], outputRange: [0.5, 1.6, 0.5] });
  const shockwaveOpacity = loopAnim.interpolate({ inputRange: [0, 0.5, 1], outputRange: [0.1, 0.9, 0.1] });

  return (
    <View style={{ width: 140, height: 110, justifyContent: 'center', alignItems: 'center', marginVertical: 2 }}>
      <Svg width="140" height="110" viewBox="0 0 140 110">
        <Path d="M 15 88 Q 70 10 110 52" fill="none" stroke="#38bdf8" strokeWidth="2.5" strokeDasharray="4,4" opacity="0.8" />
      </Svg>
      {/* Catch Shockwave Ring */}
      <Animated.View style={{ position: 'absolute', top: 32, right: 18, transform: [{ scale: shockwaveScale }], opacity: shockwaveOpacity }}>
        <Svg width="60" height="60" viewBox="0 0 60 60">
          <Circle cx="30" cy="30" r="24" fill="#10b981" opacity="0.4" />
        </Svg>
      </Animated.View>
      {/* Fielding Glove */}
      <Animated.View style={{ position: 'absolute', top: 30, right: 24, transform: [{ scale: gloveScale }] }}>
        <Text style={{ fontSize: 38 }}>🧤</Text>
      </Animated.View>
      {/* Flying Spinning Ball */}
      <Animated.View style={{ position: 'absolute', top: 40, left: 38, transform: [{ translateX: ballTranslateX }, { translateY: ballTranslateY }, { rotate: ballRotate }] }}>
        <RealisticCricketLeatherBall size={22} />
      </Animated.View>
    </View>
  );
}

// 3. LBW (Laser Hawkeye Beam, Pad Impact Ring & Pulsing Raised Umpire Finger)
