  if (!striker) striker = (activeBattingSquad.find(p => !isBatterOut(p)) || 'Striker');
  if (!nonStriker) nonStriker = (activeBattingSquad.find(p => p !== striker && !isBatterOut(p)) || 'Non-Striker');

