                <View style={styles.bowlerSummaryRow}>
                  <View style={styles.bowlerMetricBox}>
                    <Text style={styles.bowlerMetricLabel}>DOT BALLS</Text>
                    <Text style={[styles.bowlerMetricVal, { color: '#34d399' }]}>{selectedBowlerDetails.dotBalls}</Text>
                    <Text style={styles.bowlerMetricSub}>{selectedBowlerDetails.dotPct} dot %</Text>
                  </View>
                  <View style={styles.bowlerMetricBox}>
                    <Text style={styles.bowlerMetricLabel}>4s CONCEDED</Text>
                    <Text style={[styles.bowlerMetricVal, { color: '#fb923c' }]}>{selectedBowlerDetails.foursConceded}</Text>
                    <Text style={styles.bowlerMetricSub}>{selectedBowlerDetails.foursConceded * 4} runs</Text>
                  </View>
                  <View style={styles.bowlerMetricBox}>
                    <Text style={styles.bowlerMetricLabel}>6s CONCEDED</Text>
                    <Text style={[styles.bowlerMetricVal, { color: '#f87171' }]}>{selectedBowlerDetails.sixesConceded}</Text>
                    <Text style={styles.bowlerMetricSub}>{selectedBowlerDetails.sixesConceded * 6} runs</Text>
                  </View>
                </View>

